/*
	Inspired Neon Lights // 28.6.2023
	#minacoding #p5js #creativecoding #generativeart #dailycoding
	https://www.twitch.tv/videos/1857899385

	Inspired by light studies from @zachlieberman
	https://twitter.com/zachlieberman/status/1449782484720406532
*/


var bars = [];
var clrs = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(30);

	clrs = ["white", "white", "cyan", "red", "yellow", "yellow"];

	const minWH = max(width, height);
	const tileS = minWH * 1 / 6;

	bars = [];
	for (let y = (height - minWH + tileS) * 0.5; y <= height; y += tileS) {
		for (let x = (width - minWH + tileS) * 0.5; x <= width; x += tileS) {
			bars.push(new NeonBar(x, y, random(TWO_PI), tileS, random(clrs), 100));	
		}
	}
}

function draw() {
	background(0, 0, 8, 64);

	for (let b of bars) {
		b.update();
		b.show();
	}

	// // noLoop() removed for animation
}

class NeonBar {
	constructor(x, y, a, l, clr, len, act = true) {
		this.x = x;
		this.y = y;
		this.a = a;
		this.l = l;
		this.clr = clr;
		this.len = len;
		this.act = act;
	}

	update() {
		this.a = floor(4  * noise(this.x * 0.01 + frameCount * 0.021, this.y * 0.0273)) / 4 * TWO_PI + PI * 0.25;
		this.act = noise(this.x * 0.01 + frameCount * 0.021, this.y * 0.03) < 0.45
		this.clr = clrs[floor(clrs.length * (noise(this.x * 0.02 + frameCount * 0.0121, this.y * 0.023)))];
	}

	show() {
		// only draw active bars
		if (!this.act) return;

		push();
		noFill();
		noStroke();
		translate(this.x, this.y);
		rotate(this.a); 
		rectMode(CENTER);

		fill(this.clr);
		drawingContext.shadowColor = this.clr;
		drawingContext.shadowBlur = this.len;
		rect(0, 0, this.l, 4);

		drawingContext.shadowColor = "white";
		drawingContext.shadowBlur = this.len * 0.5;
		rect(0, 0, this.l, 4);

		drawingContext.shadowColor = this.clr;
		drawingContext.shadowBlur = this.len * 0.25;
		rect(0, 0, this.l, 4);

		pop();
	}
}
